import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"历史记录","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 搜索记录（Search History）","slug":"_1-搜索记录-search-history","link":"#_1-搜索记录-search-history","children":[]},{"level":2,"title":"2. 关键字记录（Keyword History）","slug":"_2-关键字记录-keyword-history","link":"#_2-关键字记录-keyword-history","children":[]},{"level":2,"title":"3. 查询关联（Query Associations）","slug":"_3-查询关联-query-associations","link":"#_3-查询关联-query-associations","children":[]}],"relativePath":"zh-CN/user-guide/settings/history.md","filePath":"zh-CN/user-guide/settings/history.md","lastUpdated":1792776074000}`),a={name:`zh-CN/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="历史记录" tabindex="-1">历史记录 <a class="header-anchor" href="#历史记录" aria-label="Permalink to “历史记录”">​</a></h1><p>历史记录页面通过三个相互独立的标签页管理使用频率、输入词条与跨名关联：<strong>搜索记录</strong>、<strong>关键字记录</strong>与<strong>查询关联</strong>。</p><h2 id="_1-搜索记录-search-history" tabindex="-1">1. 搜索记录（Search History） <a class="header-anchor" href="#_1-搜索记录-search-history" aria-label="Permalink to “1. 搜索记录（Search History）”">​</a></h2><p>搜索记录按路径统计实际打开过的文件、文件夹与应用程序的使用频率和最近时间：</p><ul><li><strong>同级衰减微调</strong>：高频使用的项目按 90 天半衰期计算有效分，仅在<strong>同一文本匹配等级内</strong>优先排列，绝不会越过完整或更干净的直接名称命中。</li><li><strong>内嵌窗口智能分区</strong>：在文件选择对话框的内嵌搜索中，当前目录内项目归入“当前文件夹”，其余归入“全局搜索”，同层内直接命中始终排在学习关联之前。</li><li><strong>失效路径自动过滤</strong>：被移动或删除的路径在检索时自动跳过，保证列表不重复、无死链。</li><li><strong>管理操作</strong>：支持<strong>启用历史记录</strong>总开关、关键词过滤、<strong>清除少于等于 N 次的记录</strong>、单条删除、<strong>清空全部记录</strong>以及跨窗口实时刷新。</li></ul><h2 id="_2-关键字记录-keyword-history" tabindex="-1">2. 关键字记录（Keyword History） <a class="header-anchor" href="#_2-关键字记录-keyword-history" aria-label="Permalink to “2. 关键字记录（Keyword History）”">​</a></h2><p>关键字记录记忆实际执行过结果或动作，或用于打开完整窗口的<strong>原始查询字符串</strong>。仅输入关键词后关闭快速搜索窗口不会新增记录：</p><ul><li><strong>快捷键快速翻阅</strong>：在快速搜索窗口中按 <strong><code>Alt+Up</code></strong> / <strong><code>Alt+Down</code></strong> 翻阅最近搜索词，按 <strong><code>Ctrl+Delete</code></strong> 直接删除当前词条。</li><li><strong>独立清理维护</strong>：提供独立的启用开关、搜索过滤、按次数阈值清理、单条删除与清空全部功能。</li></ul><h2 id="_3-查询关联-query-associations" tabindex="-1">3. 查询关联（Query Associations） <a class="header-anchor" href="#_3-查询关联-query-associations" aria-label="Permalink to “3. 查询关联（Query Associations）”">​</a></h2><p>查询关联独立存储已确认的 <strong>查询词 → 目标路径</strong> 习惯映射，与路径使用频率完全分离：</p><ul><li><strong>3 次自然打开门槛</strong>：同一规范化查询词下至少<strong>自然打开 3 次</strong>后，才会在后续输入时补充召回该目标，避免偶尔误点一次就长期污染结果。</li><li><strong>阻断自强化与尾部补充</strong>：点击由查询关联补充出的条目不会反向自增未确认计数，不召回低优先级缓存路径，且始终排在直接文本命中之后。</li><li><strong>独立清理</strong>：可随时筛选、单条删除或清空全部查询关联，而不会重置路径使用频率。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};